          monthShowsDuplicateDaysEnd={monthShowsDuplicateDaysEnd}
          monthShowsDuplicateDaysStart={monthShowsDuplicateDaysStart}
          dayNamesHeader={this.renderDayNamesHeader(monthDate, i)}
        />
      </div>,
    );
  }

